    // Default memberwise initializers are never public by default, so we
    // declare one manually.
    public init(namespace: String, identifier: String, 
        /**
         * CBOR-encoded element value; the app decodes what it needs.
         */valueCbor: Data) {
        self.namespace = namespace
        self.identifier = identifier
        self.valueCbor = valueCbor
    }
}



extension Element: Equatable, Hashable {
    public static func ==(lhs: Element, rhs: Element) -> Bool {
        if lhs.namespace != rhs.namespace {
            return false
        }
        if lhs.identifier != rhs.identifier {
            return false
        }
        if lhs.valueCbor != rhs.valueCbor {
            return false
        }
        return true
    }

    public func hash(into hasher: inout Hasher) {
        hasher.combine(namespace)
        hasher.combine(identifier)
        hasher.combine(valueCbor)
    }
}


