        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .Rejected(
            code: try FfiConverterString.read(from: &buf), 
            detail: try FfiConverterString.read(from: &buf)
            )
        case 2: return .SessionOver(
            status: try FfiConverterUInt64.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: FfiError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .Rejected(code,detail):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(code, into: &buf)
            FfiConverterString.write(detail, into: &buf)
            
        
        case let .SessionOver(status):
            writeInt(&buf, Int32(2))
            FfiConverterUInt64.write(status, into: &buf)
            
        }
    }
}


